import java.io.*;
import java.util.*;

public class TextAnalysis3 {
    static int insideBraceWordCount = 0, maxWordLen = 0;

    public static int countWordsInString(String str) {
        str = str.replaceAll("_", " ");
        str = str.trim().replaceAll(" +", " ");
        String[] tokens = str.split(" ");
        if (tokens.length == 1 && tokens[0].isEmpty()) return 0;
        return tokens.length;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int totalInputs = sc.nextInt();
        String inputStr = sc.next();
        List<Integer> bracePositions = new ArrayList<>();
        bracePositions.add(-1);
        for (int i = 0; i < inputStr.length(); i++) {
            if (inputStr.charAt(i) == '(' || inputStr.charAt(i) == ')') {
                bracePositions.add(i);
            }
        }
        int index = 1, totalWords = 0, maxWordLength = 0;
        String outsideContent = "";
        while (index < bracePositions.size() - 1) {
            int start = bracePositions.get(index);
            int end = bracePositions.get(index + 1);
            String insideBrace = inputStr.substring(start + 1, end);
            int countWords = countWordsInString(insideBrace);
            insideBraceWordCount += countWords;
            outsideContent += "_" + inputStr.substring(bracePositions.get(index - 1) + 1, start);
            index += 2;
        }
        outsideContent += "_" + inputStr.substring(bracePositions.get(bracePositions.size() - 1) + 1);
        outsideContent = outsideContent.replaceAll("_", " ");
        outsideContent = outsideContent.trim().replaceAll(" +", " ");
        String[] outsideWords = outsideContent.split(" ");
        for (String w : outsideWords) {
            if (w.length() > maxWordLen)
                maxWordLen = w.length();
        }
        System.out.print(maxWordLen + " " + insideBraceWordCount);
    }
}
